// Bundle the MCP server into one dependency-free file (foundry-mcp.mjs)
// that ships inside the module package, so users only need Node.js.
import { build } from 'esbuild';

await build({
  entryPoints: ['src/main.mjs'],
  outfile: 'foundry-mcp.mjs',
  bundle: true,
  platform: 'node',
  format: 'esm',
  target: 'node18',
  legalComments: 'eof',
  // ws optionally loads these native accelerators; it works without them.
  external: ['bufferutil', 'utf-8-validate'],
  banner: {
    js: [
      '// Simulacrum Foundry VTT MCP server. Generated by mcp/build.mjs - do not edit.',
      "import { createRequire as __createRequire } from 'node:module';",
      'const require = __createRequire(import.meta.url);',
    ].join('\n'),
  },
});
console.log('Built foundry-mcp.mjs');
